mapper.select:
select
f.file_relation_id as fileRelationId, mn.* from Completion_Acceptance_All mn
left join Sys_File f on f.FileID=mn.Caa_Id where mn.Caa_Id=#{caaId}

select

mn.*
from Completion_Acceptance_All mn


    ${params.authSql}


    where 1=1



    
        order by mn.${params.sortFiled} ${params.sortType}
    
    
        order by ${params.sortSideFiled} ${params.sortType}
    
    
        order by mn.Caa_Create_Time DESC
